package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code householdSize}: the number of owners sharing this owner's
 * {@code householdId} once this create completes.
 *
 * <p>Runs after {@link AssignHouseholdId} — so the joining owner already carries its
 * {@code householdId} and every existing member has been back-filled with it — but before
 * {@link SaveOwner}, so the new owner is not yet persisted. The count is therefore the existing
 * members that share the identifier plus one for this owner.
 *
 * <p>When the owner is not part of a household ({@code householdId} is null), the size is one.
 */
public class AssignHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int size = 1; // this owner, not yet persisted
        String householdId = owner.getHouseholdId();
        if (householdId != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (householdId.equals(existing.getHouseholdId())) {
                    size++;
                }
            }
        }
        owner.setHouseholdSize(size);
    }
}
===== RequireUniqueOwnerHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdDuplicateException;

/**
 * Rejects the create when another owner already shares this owner's household: the same
 * {@code lastName} and {@code address}, compared case-insensitively with runs of whitespace
 * collapsed to a single space. A match is rejected 409 via
 * {@link OwnerHouseholdDuplicateException}.
 *
 * <p>Bypassed when the request sets {@code sharesHousehold} true — the caller has confirmed
 * the two owners knowingly live together.
 */
public class RequireUniqueOwnerHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerHouseholdDuplicateException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (normalize(existing.getLastName()).equals(lastName)
                    && normalize(existing.getAddress()).equals(address)) {
                throw new OwnerHouseholdDuplicateException(request.getLastName(),
                        request.getAddress());
            }
        }
    }

    /** Lower-case, trimmed, with internal whitespace runs collapsed to a single space. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== NormalizeOwnerAddress =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Normalizes the address of the validated body (published by {@link RequireOwnerFields}) into
 * a canonical form: leading/trailing whitespace is trimmed, internal whitespace runs are
 * collapsed to a single space, the whole value is upper-cased, and common abbreviations are
 * expanded to their full word ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code ROAD},
 * {@code AVE}&rarr;{@code AVENUE}). The canonical value is written back onto the body in place,
 * so {@link BuildOwner} stores it and later reads/responses return it.
 *
 * <p>Runs after {@link RequireOwnerFields} — which already rejects an address that is blank
 * after normalization — and before the household steps, so
 * {@link RequireUniqueOwnerHousehold duplicate detection} and
 * {@link AssignHouseholdId the shared household id} both compare the normalized form.
 */
public class NormalizeOwnerAddress {

    public void service(@Val OwnerFieldsDto request) {
        request.setAddress(normalize(request.getAddress()));
    }

    /**
     * Trimmed, internal whitespace collapsed to a single space, upper-cased, with common
     * abbreviations expanded to their full word. Returns {@code ""} for a null or blank value.
     * Shared with {@link RequireOwnerFields} so the required-field check rejects an address
     * that is blank after normalization.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(expand(tokens[i]));
        }
        return sb.toString();
    }

    /** Expands a single upper-cased token when it is a known abbreviation, else returns it. */
    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}
===== OwnerIdentity =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * The single derived identity of an owner used for duplicate detection.
 *
 * <p>The {@code identityKey} consolidates the former separate telephone, email and household
 * duplicate checks into ONE value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
 * householdId}. Two owners are duplicates only when their WHOLE key is equal, so — because the
 * telephone is part of the key — two members of the same household (same {@code householdId})
 * with different telephones have different keys and are both allowed.
 *
 * <ul>
 *   <li>telephone — normalized to E.164 with {@link NormalizeOwnerTelephone#toE164(String)} so
 *       equivalent numbers in different formats collide; the raw value is used only as a
 *       fallback when it cannot form a valid E.164 number.</li>
 *   <li>email — lower-cased so addresses differing only in case collide; a null or blank email
 *       contributes an empty segment.</li>
 *   <li>householdId — the shared household identifier, or an empty segment when the owner is not
 *       part of a household.</li>
 * </ul>
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** Builds the {@code telephone|email|householdId} identity key. */
    public static String identityKey(String telephone, String email, String householdId) {
        String tel = NormalizeOwnerTelephone.toE164(telephone);
        if (tel == null) {
            tel = telephone == null ? "" : telephone;
        }
        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase();
        String hh = householdId == null ? "" : householdId;
        return tel + "|" + mail + "|" + hh;
    }
}
