===== AssignPossibleDuplicate =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags a soft (possible) duplicate. An owner that is not a hard identity duplicate (that check
 * runs earlier and rejects with 409) but that shares an existing owner's {@code lastName}
 * (case-insensitive) and {@code postcode} is still created, with {@code possibleDuplicate} set true
 * and {@code possibleDuplicateOf} set to the matching owner's id. When several owners match, the
 * earliest (lowest id) is chosen. Otherwise {@code possibleDuplicate} is false and
 * {@code possibleDuplicateOf} is absent.
 *
 * <p>Runs before {@link SaveOwner}, so the new owner is not yet persisted and only pre-existing
 * owners are considered.
 */
public class AssignPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        Integer matchId = null;
        if (postcode != null && !postcode.isBlank()) {
            for (Owner existing : ownerRepository.findAll()) {
                if (existing.getId() == null || existing.getId().equals(owner.getId())) {
                    continue; // never match the new owner against itself
                }
                if (equalsIgnoreCase(existing.getLastName(), lastName)
                        && postcode.equals(existing.getPostcode())) {
                    if (matchId == null || existing.getId() < matchId) {
                        matchId = existing.getId();
                    }
                }
            }
        }
        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}
===== AssignMembershipLevel =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's numeric {@code membershipLevel} (1 to 3), scored at creation:
 * start at {@code 1}; add {@code 1} when an email is present; add {@code 1} when
 * {@code namesakeCount} is {@code 0}; capped at {@code 3} (level 4 is reserved for tenure).
 *
 * <p>Runs after {@link AssignNamesakeCount} (so the namesake count is set) and before
 * {@link SaveOwner}, so the level is persisted and available to the create audit line.
 */
public class AssignMembershipLevel {

    public void service(@Val Owner owner) {
        int level = 1;
        String email = owner.getEmail();
        if (email != null && !email.isBlank()) {
            level++;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            level++;
        }
        owner.setMembershipLevel(Math.min(level, 3));
    }
}
===== AssignNamesakeCount =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code namesakeCount}: the number of existing owners that already share
 * this owner's {@code firstName} and {@code lastName}, compared case-insensitively.
 *
 * <p>Runs before {@link SaveOwner}, so the new owner is not yet persisted and the count
 * reflects only the owners that existed before this create.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsIgnoreCase(existing.getFirstName(), firstName)
                    && equalsIgnoreCase(existing.getLastName(), lastName)) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}
